    "How does the AI prediction model work for egg yields?": "How does the AI prediction model work for egg yields?",
    "Our AI algorithm analyzes historical flock data, daily feed consumption, water intake, temperature, and breed-specific laying curves to accurately forecast egg production 7–14 days in advance, alerting you to low-performance batches before yields drop.": "Our AI algorithm analyzes historical flock data, daily feed consumption, water intake, temperature, and breed-specific laying curves to accurately forecast egg production 7–14 days in advance, alerting you to low-performance batches before yields drop.",
    "Can I integrate this with my current CCTV cameras?": "Can I integrate this with my current CCTV cameras?",
    "Yes! PFMS supports standard RTSP, ONVIF, and IP camera feeds. Our AI surveillance engine connects directly to your existing CCTV streams to detect nighttime predators, flock distress, and unauthorized human motion.": "Yes! PFMS supports standard RTSP, ONVIF, and IP camera feeds. Our AI surveillance engine connects directly to your existing CCTV streams to detect nighttime predators, flock distress, and unauthorized human motion.",
    "What kind of support do you offer?": "What kind of support do you offer?",
    "Commercial Pro users receive 24/7 dedicated WhatsApp support, priority technician hotline, and automated daily AI report summaries delivered straight to management.": "Commercial Pro users receive 24/7 dedicated WhatsApp support, priority technician hotline, and automated daily AI report summaries delivered straight to management.",
    "Is there a free trial or free tier available?": "Is there a free trial or free tier available?",
    "Yes! You can start on our Free Starter Plan immediately with zero credit card required. Free tier includes up to 1 branch, 2 staff members, full flock tracking, and inventory logs.": "Yes! You can start on our Free Starter Plan immediately with zero credit card required. Free tier includes up to 1 branch, 2 staff members, full flock tracking, and inventory logs.",
    "How do customer invoices and online payments work?": "How do customer invoices and online payments work?",
    "PFMS automatically generates professional customer invoices with built-in Paystack & Stripe payment links. Once a customer pays online or you mark it as paid offline, the invoice automatically updates your financial ledger and logs a verified sale.": "PFMS automatically generates professional customer invoices with built-in Paystack & Stripe payment links. Once a customer pays online or you mark it as paid offline, the invoice automatically updates your financial ledger and logs a verified sale.",
