    "How does the AI prediction model work for egg yields?": "产蛋量 AI 预测模型是如何运作的？",
    "Our AI algorithm analyzes historical flock data, daily feed consumption, water intake, temperature, and breed-specific laying curves to accurately forecast egg production 7–14 days in advance, alerting you to low-performance batches before yields drop.": "我们的 AI 算法分析历史鸡群数据、每日饲料消耗、饮水量、温度和品种特异性产蛋曲线，提前 7-14 天精准预测产蛋量，在产量下降前向您提示低效批次。",
    "Can I integrate this with my current CCTV cameras?": "我可以将系统与现有的监控摄像头集成吗？",
    "Yes! PFMS supports standard RTSP, ONVIF, and IP camera feeds. Our AI surveillance engine connects directly to your existing CCTV streams to detect nighttime predators, flock distress, and unauthorized human motion.": "可以！PFMS 支持标准 RTSP、ONVIF 和 IP 摄像头接入。我们的 AI 监控引擎直接连接您现有的 CCTV 视频流，以检测夜间掠食者、鸡群应激和异常人员走动。",
    "What kind of support do you offer?": "你们提供什么样的技术支持？",
    "Commercial Pro users receive 24/7 dedicated WhatsApp support, priority technician hotline, and automated daily AI report summaries delivered straight to management.": "Commercial Pro 用户享有 24/7 专属 WhatsApp 支持、优先技术热线，以及直接发送给管理层的每日自动 AI 报告摘要。",
    "Is there a free trial or free tier available?": "是否有免费试用或免费版本？",
    "Yes! You can start on our Free Starter Plan immediately with zero credit card required. Free tier includes up to 1 branch, 2 staff members, full flock tracking, and inventory logs.": "有！您可以立即使用我们的 Free Starter 计划，无需信用卡。免费版包含最多 1 个分部、2 名员工、完整鸡群跟踪和饲料库存记录。",
    "How do customer invoices and online payments work?": "客户发票与在线支付如何运作？",
    "PFMS automatically generates professional customer invoices with built-in Paystack & Stripe payment links. Once a customer pays online or you mark it as paid offline, the invoice automatically updates your financial ledger and logs a verified sale.": "PFMS 自动生成附带 Paystack 和 Stripe 付款链接的专业客户发票。一旦客户在线付款或您离线标记为已付，发票会自动更新财务总账并记录已验证的销售。",
    "Simple, transparent pricing": "简单、透明的价格方案",
    "Choose the plan that fits your farm's size and needs. Upgrade anytime as your flock grows.": "选择适合您养殖场规模和需求的方案。随着鸡群扩张，可随时升级。",
    "Perfect for small farms getting started with digital log management.": "非常适合刚开始进行数字化日志管理的小型养殖场。",
    "1 Farm Branch Included": "包含 1 个养殖分部",
    "Basic Egg Collection & Feed Tracking": "基础产蛋记录与饲料跟踪",
    "Basic Flock Mortality & Weight Logs": "基础鸡群死亡率与体重记录",
    "2 Staff Accounts": "2 个员工账户",
