    "Maintenance Mode": "Mode Pemeliharaan",
    "How does the AI prediction model work for egg yields?": "Bagaimana cara kerja model prediksi AI untuk hasil produksi telur?",
    "Our AI algorithm analyzes historical flock data, daily feed consumption, water intake, temperature, and breed-specific laying curves to accurately forecast egg production 7–14 days in advance, alerting you to low-performance batches before yields drop.": "Algoritma AI kami menganalisis data historis kawanan, konsumsi pakan harian, asupan air, suhu, dan kurva bertelur spesifik ras untuk memprediksi produksi telur 7–14 hari sebelumnya secara akurat, memberi tahu Anda tentang kawanan berkinerja rendah sebelum hasil turun.",
    "Can I integrate this with my current CCTV cameras?": "Dapatkah saya mengintegrasikannya dengan kamera CCTV saya saat ini?",
    "Yes! PFMS supports standard RTSP, ONVIF, and IP camera feeds. Our AI surveillance engine connects directly to your existing CCTV streams to detect nighttime predators, flock distress, and unauthorized human motion.": "Ya! PFMS mendukung feed kamera standar RTSP, ONVIF, dan IP. Mesin pengawasan AI kami terhubung langsung ke streaming CCTV Anda untuk mendeteksi predator malam, stres kawanan, dan gerakan manusia tanpa izin.",
    "What kind of support do you offer?": "Dukungan seperti apa yang Anda tawarkan?",
    "Commercial Pro users receive 24/7 dedicated WhatsApp support, priority technician hotline, and automated daily AI report summaries delivered straight to management.": "Pengguna Commercial Pro menerima dukungan WhatsApp khusus 24/7, hotline teknisi prioritas, dan ringkasan laporan harian otomatis AI yang dikirimkan langsung ke manajemen.",
    "Is there a free trial or free tier available?": "Apakah ada uji coba gratis atau tingkat gratis yang tersedia?",
    "Yes! You can start on our Free Starter Plan immediately with zero credit card required. Free tier includes up to 1 branch, 2 staff members, full flock tracking, and inventory logs.": "Ya! Anda dapat langsung memulai Paket Pemula Gratis tanpa memerlukan kartu kredit. Paket gratis mencakup hingga 1 cabang, 2 staf, pelacakan kawanan lengkap, dan log inventaris.",
    "How do customer invoices and online payments work?": "Bagaimana cara kerja faktur pelanggan dan pembayaran online?",
    "PFMS automatically generates professional customer invoices with built-in Paystack & Stripe payment links. Once a customer pays online or you mark it as paid offline, the invoice automatically updates your financial ledger and logs a verified sale.": "PFMS secara otomatis menghasilkan faktur pelanggan profesional dengan tautan pembayaran Paystack & Stripe bawaan. Setelah pelanggan membayar secara online atau Anda menandainya dibayar secara offline, faktur secara otomatis memperbarui buku besar keuangan Anda dan mencatat penjualan terverifikasi.",
    "Simple, transparent pricing": "Harga yang sederhana dan transparan",
    "Choose the plan that fits your farm's size and needs. Upgrade anytime as your flock grows.": "Pilih paket yang sesuai dengan ukuran dan kebutuhan peternakan Anda. Tingkatkan kapan saja seiring bertambahnya kawanan Anda.",
    "Perfect for small farms getting started with digital log management.": "Sempurna untuk peternakan kecil yang baru memulai manajemen pencatatan digital.",
    "1 Farm Branch Included": "Termasuk 1 Cabang Peternakan",
