    "Maintenance Mode": "रखरखाव मोड",
    "How does the AI prediction model work for egg yields?": "अंडा उत्पादन के लिए एआई भविष्यवाणी मॉडल कैसे काम करता है?",
    "Our AI algorithm analyzes historical flock data, daily feed consumption, water intake, temperature, and breed-specific laying curves to accurately forecast egg production 7–14 days in advance, alerting you to low-performance batches before yields drop.": "हमारा एआई एल्गोरिदम ऐतिहासिक झुंड डेटा, दैनिक फ़ीड खपत, पानी का सेवन, तापमान और नस्ल-विशिष्ट उत्पादन घटता का विश्लेषण करके 7-14 दिन पहले अंडे के उत्पादन का सटीक पूर्वानुमान लगाता है, जिससे उत्पादन घटने से पहले आपको अलर्ट मिल जाता है।",
    "Can I integrate this with my current CCTV cameras?": "क्या मैं इसे अपने मौजूदा सीसीटीवी कैमरों के साथ एकीकृत कर सकता हूँ?",
    "Yes! PFMS supports standard RTSP, ONVIF, and IP camera feeds. Our AI surveillance engine connects directly to your existing CCTV streams to detect nighttime predators, flock distress, and unauthorized human motion.": "हाँ! PFMS मानक RTSP, ONVIF और IP कैमरा फ़ीड का समर्थन करता है। हमारा एआई निगरानी इंजन रात के शिकारियों, झुंड के संकट और अनधिकृत मानवीय गतिविधियों का पता लगाने के लिए आपके मौजूदा सीसीटीवी स्ट्रीम से जुड़ता है।",
    "What kind of support do you offer?": "आप किस प्रकार की सहायता प्रदान करते हैं?",
    "Commercial Pro users receive 24/7 dedicated WhatsApp support, priority technician hotline, and automated daily AI report summaries delivered straight to management.": "कमर्शियल प्रो उपयोगकर्ताओं को 24/7 समर्पित व्हाट्सएप सहायता, प्राथमिकता तकनीशियन हॉटलाइन और प्रबंधन को सीधे दी जाने वाली दैनिक स्वचालित एआई रिपोर्ट सारांश प्राप्त होते हैं।",
    "Is there a free trial or free tier available?": "क्या कोई नि:शुल्क परीक्षण या नि:शुल्क योजना उपलब्ध है?",
    "Yes! You can start on our Free Starter Plan immediately with zero credit card required. Free tier includes up to 1 branch, 2 staff members, full flock tracking, and inventory logs.": "हाँ! आप बिना किसी क्रेडिट कार्ड के तुरंत हमारे फ्री स्टार्टर प्लान पर शुरुआत कर सकते हैं। नि:शुल्क योजना में 1 शाखा, 2 कर्मचारी सदस्य, पूर्ण झुंड ट्रैकिंग और इन्वेंट्री लॉग शामिल हैं।",
    "How do customer invoices and online payments work?": "ग्राहक चालान और ऑनलाइन भुगतान कैसे काम करते हैं?",
    "PFMS automatically generates professional customer invoices with built-in Paystack & Stripe payment links. Once a customer pays online or you mark it as paid offline, the invoice automatically updates your financial ledger and logs a verified sale.": "PFMS इनबिल्ट पेस्टैक और स्ट्राइप भुगतान लिंक के साथ पेशेवर ग्राहक चालान स्वचालित रूप से तैयार करता है। एक बार जब कोई ग्राहक ऑनलाइन भुगतान करता है या आप ऑफ़लाइन भुगतान के रूप में चिह्नित करते हैं, तो चालान स्वचालित रूप से आपके वित्तीय बहीखाते को अपडेट करता है और एक सत्यापित बिक्री दर्ज करता है।",
    "Simple, transparent pricing": "सरल और पारदर्शी मूल्य निर्धारण",
    "Choose the plan that fits your farm's size and needs. Upgrade anytime as your flock grows.": "अपनी फ़ार्म की आवश्यकता और आकार के अनुसार योजना चुनें। जैसे-जैसे आपका झुंड बढ़ता है, कभी भी अपग्रेड करें।",
    "Perfect for small farms getting started with digital log management.": "डिजिटल लॉग प्रबंधन शुरू करने वाले छोटे फार्मों के लिए बिल्कुल उपयुक्त।",
