    "How does the AI prediction model work for egg yields?": "Je, mfumo wa utabiri wa AI wa uzalishaji wa mayai unafanyaje kazi?",
    "Our AI algorithm analyzes historical flock data, daily feed consumption, water intake, temperature, and breed-specific laying curves to accurately forecast egg production 7–14 days in advance, alerting you to low-performance batches before yields drop.": "Kanuni zetu za AI huchanganua data ya kundi, matumizi ya kila siku ya chakula, maji, halijoto na mikondo ya utagaji ili kutabiri kwa usahihi uzalishaji wa mayai siku 7–14 kabla, kukutaarifu kabla mavuno hayajashuka.",
    "Can I integrate this with my current CCTV cameras?": "Je, ninaweza kuiunganisha na kamera zangu za sasa za CCTV?",
    "Yes! PFMS supports standard RTSP, ONVIF, and IP camera feeds. Our AI surveillance engine connects directly to your existing CCTV streams to detect nighttime predators, flock distress, and unauthorized human motion.": "Ndiyo! PFMS inasaidia kamera za kawaida za RTSP, ONVIF na IP. Injini yetu ya ufuatiliaji wa AI huunganishwa moja kwa moja na kamera zako ili kugundua wanyama waharibifu usiku, msongo wa kuku, na harakati zisizoidhinishwa za binadamu.",
    "What kind of support do you offer?": "Je, unatoa huduma gani ya usaidizi?",
    "Commercial Pro users receive 24/7 dedicated WhatsApp support, priority technician hotline, and automated daily AI report summaries delivered straight to management.": "Watumiaji wa Commercial Pro wanapata usaidizi wa saa 24/7 wa WhatsApp, simu ya dharura ya mafundi, na muhtasari wa ripoti za kila siku za AI zinazotumwa moja kwa moja kwa wasimamizi.",
    "Is there a free trial or free tier available?": "Je, kuna jaribio la bure au mpango wa bure unaopatikana?",
    "Yes! You can start on our Free Starter Plan immediately with zero credit card required. Free tier includes up to 1 branch, 2 staff members, full flock tracking, and inventory logs.": "Ndiyo! Unaweza kuanza kwenye Mpango wetu wa Bure wa Kuanzia mara moja bila kadi ya mkopo. Ngazi ya bure inajumuisha tawi 1, wafanyakazi 2, ufuatiliaji kamili wa kundi na kumbukumbu za hesabu.",
    "How do customer invoices and online payments work?": "Je, ankara za wateja na malipo ya mtandaoni yanafanyaje kazi?",
    "PFMS automatically generates professional customer invoices with built-in Paystack & Stripe payment links. Once a customer pays online or you mark it as paid offline, the invoice automatically updates your financial ledger and logs a verified sale.": "PFMS huzalisha ankara za kitaalamu za wateja zikiwa na viungo vya malipo vya Paystack na Stripe. Mteja akilipa mtandaoni au ukithibitisha malipo ya taslimu, ankara husasisha daftari la fedha na kurekodi mauzo rasmi.",
    "Simple, transparent pricing": "Bei rahisi na zilizo wazi",
    "Choose the plan that fits your farm's size and needs. Upgrade anytime as your flock grows.": "Chagua mpango unaofaa ukubwa na mahitaji ya shamba lako. Boresha wakati wowote kundi lako linapokua.",
    "Perfect for small farms getting started with digital log management.": "Inafaa kwa mashamba madogo yanayoanza usimamizi wa kumbukumbu za kidijitali.",
    "1 Farm Branch Included": "Tawi 1 la Shamba Limejumuishwa",
