    "Paste your daily report below. The AI will automatically extract egg collections, feed usage, and mortality figures to update your records.": "Weka ripoti yako ya kila siku hapa chini. AI itachambua na kurekodi uvunaji wa mayai, matumizi ya chakula na vifo vya kuku ili kusasisha kumbukumbu zako.",
    "Daily Farm Report": "Ripoti ya Kila Siku ya Shamba",
    "Example: Today we collected 4500 good eggs, but 12 were cracked. Unfortunately, 3 birds died. We also spent 250000 on drugs and sold eggs for 600000.": "Mfano: Leo tumekusanya mayai mazuri 4500, lakini 12 yalipasuka. Kwa bahati mbaya kuku 3 walikufa. Tulitumia pia 250000 kwa dawa na kuuza mayai kwa 600000.",
