// Merge enterprise & CCTV translations across all languages
(Object.keys(ENTERPRISE_CCTV_PHRASES) as Language[]).forEach((lang) => {
  if (GLOBAL_PHRASES[lang]) {
    Object.assign(GLOBAL_PHRASES[lang], ENTERPRISE_CCTV_PHRASES[lang]);
  }
});


